// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock context providers
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Excalibur Replica', price: 299.99 },
  { id: '2', name: 'Round Table Coaster', price: 19.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 319.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - The Chronicle of Commerce', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-CAMELOT-001' });
  });

  // === HAPPY PATH: THE KING'S JOURNEY ===
  it('completes full checkout flow from shipping to confirmation', async () => {
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Camelot Lane');
    await user.type(screen.getByLabelText(/city/i), 'Avalon');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'King Arthur');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/excalibur replica/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-CAMELOT-001');
  });

  // === VALIDATION: THE TRIALS OF ENTRY ===
  describe('Shipping validation', () => {
    it('displays error when ZIP code format is invalid', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  // === EDGE CASES: THE TRIALS OF EMPTINESS ===
  it('shows empty cart message when no items present', async () => {
    vi.mocked(require('./CartContext').useCart).mockReturnValue({
      items: [], total: 0, clearCart: mockClearCart
    });

    render(<Checkout />);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  // === ACCESSIBILITY: THE DECREE OF INCLUSION ===
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
